#!/usr/bin/env python3
"""place-rank SAMPLE (owner Lượt 447, FIGURE_GATE 14): build the 10 prompts from dev/art/place-redraw/prompt_template.txt (RECIPE v2).
python3 dev/art/place-rank/prompts.py  -> writes prompts.json next to this file."""
import json, os
D = os.path.dirname(os.path.abspath(__file__))
T = open(os.path.join(D, '..', 'place-redraw', 'prompt_template.txt')).read().strip()
NOPE = ' No phoenix anywhere (no phoenix carving, embroidery, figure or pendant), no imperial yellow, no golden-yellow fabrics.'
NOPE_QF = ' No phoenix anywhere (no phoenix carving, embroidery, figure or pendant); yellow only as the one small accent named above, never imperial yellow silk.'
# STYLE CARDS (ROOT-48 relay of owner add to Lượt 447: each palace its own signature, same across ranks and both rooms)
CARD_CP = ("Cảnh Phúc cung signature style, the same in every room of this palace: crabapple blossoms (hải đường) are its flower, painted on the screens, "
           "embroidered on the silks and in the vases; motifs of bats among auspicious clouds carved in the beams and furniture; dark rosewood with jade-green inlay "
           "and jade ornaments; round-backed rosewood furniture; a round moon-gate opening in a carved partition. ")
# Cảnh Phúc chính điện: SAME architecture in all three versions, only the furnishing gets richer
CPA_BED = ("Cảnh Phúc cung chính điện bedroom, the private bedchamber of the imperial consort who heads this palace in ancient China, "
           "a real room in daily use: dark rosewood pillars and beams, carved lattice windows at the back opening onto a sunny courtyard "
           "garden with a tree and a lotus pond, a carved wooden partition with a round moon-gate opening; ")
CPA_REC = ("Cảnh Phúc cung chính điện reception room, the sitting room where the imperial consort who heads this palace in ancient China "
           "receives her guests, a real room in daily use, no bed anywhere: dark rosewood pillars and beams, carved lattice windows at the back "
           "opening onto a sunny courtyard garden with a tree and a lotus pond, a carved wooden partition with a round moon-gate opening; ")
RANK = {
 'tan': dict(col='pale pink', bed="one canopy bed of carved rosewood with pale pink gauze curtains tied back and pale pink silk bedding embroidered with crabapple blossoms, fine jade-green inlay on the bed frame",
             bedx="a dressing table with a bronze mirror and a small jewellery box, a small screen painted with crabapple blossoms, round stools with pale pink cushions, hanging palace lanterns with pink tassels, a clothes rack with a pink robe, a vase of crabapple branches, a small tea table, a bookshelf with boxes, slippers and a small basket on the floor",
             rec="a round-backed rosewood couch with pale pink silk cushions embroidered with crabapple blossoms and a low tea table with a tea set, two round-backed rosewood armchairs with pale pink cushions, a folding screen painted with crabapple blossoms, shelves with porcelain vases and boxes, pale pink sheer curtains tied back, hanging palace lanterns with pink tassels, vases of crabapple branches, an incense burner, an embroidery frame on a stand, potted plants",
             lux="TẦN level, the simplest of the three: pretty and noble but modest, plain polished rosewood with a little carving, few ornaments, little gilding.", nope=None),
 'phi': dict(col='soft purple', bed="one larger canopy bed of carved rosewood with soft purple gauze curtains tied back with tassels and purple silk brocade bedding embroidered with crabapple blossoms, more carving and jade-green inlay on the bed frame",
             bedx="a carved dressing table with a large bronze mirror, a lacquered jewellery cabinet and jade ornaments, a carved screen painted with crabapple blossoms, round stools with purple cushions, hanging palace lanterns with purple tassels, a clothes stand with a purple silk robe, porcelain vases of crabapple branches, a tea table with a fine tea set, a shelf with jade and porcelain treasures, a small incense burner, slippers on the floor",
             rec="a carved round-backed rosewood couch with purple brocade cushions embroidered with crabapple blossoms and a low tea table with a fine porcelain tea set, a pair of carved round-backed armchairs with purple cushions, a carved screen painted with crabapple blossoms, curio shelves with jade carvings, porcelain and lacquer boxes, soft purple sheer curtains tied back with tassels, hanging palace lanterns with purple tassels, vases of crabapple branches, a bronze incense burner, a guqin on a stand, potted plants",
             lux="PHI level, clearly richer than a Tần: more carving, more jade-green inlay, some gilt edging, silk brocade, more jade and porcelain treasures.", nope=None),
 'quyphi': dict(col='rose red', bed="one grand canopy bed of deeply carved rosewood with gilt carving, jade-green inlay and pearl strings, rose red gauze curtains tied back with tassels, rose red silk brocade bedding embroidered with crabapple blossoms, with one small accent of pale gold-yellow in the cushion trim and tassels",
             bedx="a large carved dressing table with a tall bronze mirror, a gilt lacquer jewellery cabinet open with pearls and jade, a large carved gilded screen painted with crabapple blossoms, round stools with rose red cushions, ornate hanging palace lanterns with rose red tassels, a clothes stand with a rose red silk robe, cloisonné and fine porcelain vases of crabapple branches, a coral tree ornament, a tea table with a gold-trimmed tea set, a curio shelf with jade, coral and porcelain treasures, a bronze incense burner, slippers on the floor",
             rec="a deeply carved gilt round-backed rosewood couch with rose red brocade cushions embroidered with crabapple blossoms, with one small accent of pale gold-yellow in the cushion trim, and a low tea table with a gold-trimmed porcelain tea set, a pair of carved gilt round-backed armchairs with rose red cushions, a large carved gilded screen painted with crabapple blossoms, curio shelves full of jade carvings, cloisonné, coral and porcelain treasures, rose red sheer curtains tied back with tassels, ornate hanging palace lanterns with rose red tassels, cloisonné vases of crabapple branches, a bronze incense burner, a guqin on a stand, potted plants",
             lux="QUÝ PHI level, the richest of the three: lavish gilt carving, jade-green inlay, silk brocade, pearls, coral, jade and cloisonné, yet clearly below an Empress.", nope=True),
}
ROOMS = {}
for k, r in RANK.items():
    ROOMS[f'canh-phuc-cung-{k}-ngu'] = dict(room=CPA_BED + "at the centre of the room, the large clear main subject, " + r['bed'] + "; around it " + r['bedx'] + ". " + CARD_CP + r['lux'] + f" The {r['col']} accent colour is woven through the bedding, curtains and cushions." + (NOPE_QF if r['nope'] else NOPE),
        floor='warm polished wooden floorboards', mat='the bed step', key='the canopy bed')
    ROOMS[f'canh-phuc-cung-{k}'] = dict(room=CPA_REC + r['rec'] + ". " + CARD_CP + r['lux'] + f" The {r['col']} accent colour is woven through the cushions, curtains and silks." + (NOPE_QF if r['nope'] else NOPE),
        floor='warm polished wooden floorboards', mat='the tea table', key='the couch with its tea table')
QN = "Pretty, noble and well kept, never poor: carved lacquer furniture with fine painted flowers, embroidered silk, but modest in size and luxury, a lower consort's quarters."
ROOMS['thua-minh-cung-dong-phoi-ngu'] = dict(room="Thừa Minh cung Đông phối điện bedroom, the private bedchamber of one lower-ranking imperial consort living in the east side hall of a palace in ancient China, a real room in daily use: wooden pillars, lattice windows at the back onto a sunny garden; at the centre of the room, the large clear main subject, one canopy bed with pale blue gauze curtains tied back and pale blue embroidered silk bedding and cushions, the bed of carved lacquered wood with painted flowers; around it a small dressing table with a bronze mirror, a painted screen with orchids, embroidered stools with pale blue cushions, hanging paper lanterns with blue tassels, a clothes rack with a pale blue robe, a vase of white and blue flowers, a small tea table, a shelf with a few boxes and books, slippers and a small basket on the floor. " + QN + " The pale blue accent colour is woven through the bedding, curtains and cushions. Only one bed." + NOPE,
        floor='warm polished wooden floorboards', mat='the bed step', key='the canopy bed')
ROOMS['thua-minh-cung-dong-phoi'] = dict(room="Thừa Minh cung Đông phối điện reception room, the small sitting room where a lower-ranking imperial consort living in the east side hall of a palace in ancient China receives her guests, a real room in daily use, no bed anywhere: wooden pillars, lattice windows at the back onto a sunny garden; a carved lacquered couch with pale blue silk cushions and a low tea table with a tea set, two small carved chairs with pale blue cushions, a painted folding screen with orchids, shelves with porcelain vases, books and boxes, pale blue sheer curtains tied back, hanging paper lanterns with blue tassels, vases of white and blue flowers, a small incense burner, an embroidery frame, potted plants. " + QN + " The pale blue accent colour is woven through the cushions, curtains and silks." + NOPE,
        floor='warm polished wooden floorboards', mat='the tea table', key='the couch with its tea table')
EMP = " The most dazzling room of the whole palace: imperial yellow silk and gold everywhere, phoenix motifs carved, embroidered and gilded, red lacquer pillars wrapped with gold, the richest treasures."
ROOMS['khon-ninh-cung-ngu'] = dict(room="Khôn Ninh cung bedroom, the private bedchamber of the Empress in an ancient Chinese imperial palace, a real room in daily use: red lacquer pillars with gilded phoenix carving, golden lattice windows at the back onto a sunny summer garden; at the centre of the room, the large clear main subject, one magnificent canopy bed of gilded carved wood with golden phoenixes on its crown, imperial yellow gauze curtains tied back with gold tassels, imperial yellow silk brocade bedding embroidered with phoenixes and peonies; around it a grand dressing table with a tall gilt mirror and a jewellery cabinet with gold phoenix hairpins and pearls, a gilded folding screen with a phoenix among peonies, stools with yellow brocade cushions, ornate gilded palace lanterns, a pair of golden phoenix figures on stands, cloisonné vases of peonies, a tea table with a gold tea set, a curio shelf of jade and gold treasures, a gold incense burner, slippers on the floor." + EMP,
        floor='polished stone tiles', mat='the bed dais', key='the canopy bed')
ROOMS['khon-ninh-cung'] = dict(room="Khôn Ninh cung reception hall, where the Empress of an ancient Chinese imperial palace receives the consorts, a real room in daily use, no bed anywhere: red lacquer pillars with gilded phoenix carving, golden lattice windows at the back onto a sunny summer garden; on a low dais a carved gilded throne couch with imperial yellow silk cushions embroidered with phoenixes and a low tea table with a gold tea set, behind it a large gilded folding screen with a phoenix among peonies, a pair of golden phoenix figures on tall stands, imperial yellow sheer curtains tied back with gold tassels, ornate gilded palace lanterns, side tables with cloisonné and porcelain vases of peonies, curio shelves of jade and gold treasures, a gold incense burner, a writing desk with scrolls, potted peonies." + EMP,
        floor='polished stone tiles', mat='the dais', key='the throne couch')
out = {}
for k, r in ROOMS.items():
    out[k] = (T.replace('{SEASON_TIME}', 'summer morning').replace('{TIME_LIGHT}', 'morning daylight').replace('{ROOM_LINE}', r['room'])
               .replace('{FLOOR}', r['floor']).replace('{MAT_UNDER}', r['mat']).replace('{KEY_PIECE}', r['key']))
    assert 'right side' not in r['room'] and '{' not in out[k], k
json.dump(out, open(os.path.join(D, 'prompts.json'), 'w'), ensure_ascii=False, indent=1)
print(len(out), max(len(v) for v in out.values()))
